/// Table t at slope index j (0 to 64) and distance d in 64ths, linear
/// between the samples 4 apart; 0 outside them.
fn at(t: &[[u8; STEPS]; SLOPES], j: usize, d: f64) -> f64 {
    let x = (d + 128.0) / 4.0;
    if !(x >= 0.0 && x <= (STEPS - 1) as f64) {
        return 0.0;
    }
    let i = (x.floor() as usize).min(STEPS - 2);
    let f = x - i as f64;
    t[j][i] as f64 * (1.0 - f) + t[j][i + 1] as f64 * f
}

/// Table t at |slope| s (0 to 1) and distance d, linear between slopes.
fn sample(t: &[[u8; STEPS]; SLOPES], s: f64, d: f64) -> f64 {
    let x = (s.clamp(0.0, 1.0) * 64.0).min(64.0);
    let j = (x.floor() as usize).min(SLOPES - 2);
    let f = x - j as f64;
    at(t, j, d) * (1.0 - f) + at(t, j + 1, d) * f
}

/// The coverage (0 to 1) of a pixel whose centre is `d` 64ths of a pixel
/// from a smoothed line of width `width` and |slope| `s` (minor over
/// major, 0 to 1), along the minor axis at the column centre. A line
/// wider than 2 is the width-2 edge moved out, full in between; one
/// between 1 and 2 is between the two tables.
pub(crate) fn coverage(width: f64, s: f64, d: f64) -> f64 {
    let v = if width <= 1.0 {
        sample(&WIDTH1, s, d)
    } else if width >= 2.0 {
        let plateau = (width - 2.0) * 32.0;
        if d.abs() <= plateau {
            255.0
        } else {
            sample(&WIDTH2, s, d - plateau * d.signum())
        }
    } else {
        let f = width - 1.0;
        sample(&WIDTH1, s, d) * (1.0 - f) + sample(&WIDTH2, s, d) * f
    };
    (v / 255.0).clamp(0.0, 1.0)
}

/// How far from the line, in pixels along the minor axis, a smoothed line
/// of `width` covers anything.
pub(crate) fn reach(width: f64) -> f64 {
    (width.max(2.0) - 2.0) * 0.5 + 2.0
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The table answers the measured values at its samples: a horizontal
    /// line full at its centre, half a pixel off at 139, and a 45-degree
    /// line's centre at 180.
    #[test]
    fn the_samples_are_the_measured_values() {
        assert_eq!((coverage(1.0, 0.0, 0.0) * 255.0).round(), 255.0);
        assert_eq!((coverage(1.0, 0.0, 32.0) * 255.0).round(), 139.0);
        assert_eq!((coverage(1.0, 1.0, 0.0) * 255.0).round(), 180.0);
        assert_eq!((coverage(2.0, 0.0, 0.0) * 255.0).round(), 255.0);
        assert_eq!(coverage(1.0, 0.0, 100.0), 0.0);
    }
}
